import {biddingStrategies as bids} from './google-ads-bidding-data.js';
const tabs=[...document.querySelectorAll('.ga-format-buttons [role=tab]')];
function activate(tab,focus=false){for(const t of tabs){const selected=t===tab;t.setAttribute('aria-selected',String(selected));t.tabIndex=selected?0:-1;document.getElementById(t.getAttribute('aria-controls')).hidden=!selected;}if(focus)tab.focus();}
tabs.forEach((t,i)=>{t.addEventListener('click',()=>{activate(t);document.getElementById(t.getAttribute('aria-controls')).scrollIntoView({block:'start'});});t.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=tabs.length-1;if(n!==undefined){e.preventDefault();activate(tabs[n],true);}});});
const form=document.querySelector('#ga-calculator'),budget=document.querySelector('#ga-budget'),vat=document.querySelector('#ga-vat');
const money=new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0});
function calculate(){const n=budget.valueAsNumber,r=Number(vat.value),valid=budget.validity.valid&&Number.isFinite(n)&&n>=0;document.querySelector('#ga-calc-error').textContent=valid?'':' Nhập ngân sách hợp lệ từ 0 đến 1.000 tỷ đồng.';for(const [id,value]of [['ga-base',n],['ga-tax-output',n*r/100],['ga-total',n*(1+r/100)]])document.getElementById(id).textContent=valid?money.format(value):'—';}
form.addEventListener('submit',e=>e.preventDefault());form.addEventListener('input',calculate);form.addEventListener('change',calculate);calculate();
const matchData={exact:['[thiết kế website doanh nghiệp]','Cùng ý nghĩa hoặc ý định.','Phạm vi chặt hơn; có thể khớp cách diễn đạt mang cùng ý định tìm dịch vụ.',['thiết kế website doanh nghiệp','dịch vụ thiết kế web doanh nghiệp']],phrase:['"thiết kế website doanh nghiệp"','Bao gồm ý nghĩa của từ khóa.','Có thể tiếp cận nhu cầu cụ thể hơn; ý nghĩa và thứ tự từ khi ảnh hưởng ý định đều quan trọng.',['báo giá thiết kế website doanh nghiệp','công ty thiết kế website doanh nghiệp tại Hà Nội']],broad:['thiết kế website doanh nghiệp','Mở rộng sang tìm kiếm liên quan.','Có thể dùng thêm tín hiệu như trang đích và ngữ cảnh. Cần phối hợp đo lường chuyển đổi, giá thầu và rà soát truy vấn.',['đơn vị làm trang web công ty','giải pháp xây dựng website cho doanh nghiệp']]};
for(const b of document.querySelectorAll('[data-match]'))b.addEventListener('click',()=>{for(const x of document.querySelectorAll('[data-match]'))x.setAttribute('aria-pressed',String(x===b));const [keyword,title,desc,queries]=matchData[b.dataset.match];document.querySelector('#ga-keyword').textContent=keyword;document.querySelector('#ga-match-title').textContent=title;document.querySelector('#ga-match-desc').textContent=desc;document.querySelector('#ga-query-examples').replaceChildren(...queries.map(q=>{const li=document.createElement('li');li.textContent=q;return li;}));});
document.querySelector('#ga-negative-toggle').addEventListener('change',e=>{document.querySelector('#ga-negative-row').classList.toggle('is-excluded',e.target.checked);document.querySelector('#ga-negative-result').textContent=e.target.checked?'Loại trong ví dụ vì chứa cụm từ phủ định “tuyển dụng”.':'Có dấu hiệu lệch nhu cầu mua dịch vụ.';});
const copyInputs=['ga-headline-one','ga-headline-two','ga-ad-description'].map(id=>document.getElementById(id));function updateCopy(){for(const input of copyInputs)document.getElementById(input.id+'-count').textContent=input.value.length+'/'+input.maxLength;document.getElementById('ga-copy-headline').textContent=copyInputs.slice(0,2).map(i=>i.value.trim()).filter(Boolean).join(' | ')||'Tiêu đề quảng cáo';document.getElementById('ga-copy-description').textContent=copyInputs[2].value||'Nội dung mô tả sẽ xuất hiện ở đây.';}copyInputs.forEach(i=>i.addEventListener('input',updateCopy));document.querySelector('#ga-copy-form').addEventListener('submit',e=>e.preventDefault());updateCopy();

for(const b of document.querySelectorAll('[data-bid]'))b.addEventListener('click',()=>{for(const x of document.querySelectorAll('[data-bid]'))x.setAttribute('aria-pressed',String(x===b));const ids=['tag','title','summary','input','output','need','caution','example'];bids[b.dataset.bid].forEach((value,i)=>document.getElementById('ga-bid-'+ids[i]).textContent=value);});
const goalPlans={leads:['Yêu cầu tư vấn gửi thành công; tiếp tục phân loại lead đủ điều kiện trong CRM.','Search khi nhu cầu tìm kiếm rõ; cân nhắc Demand Gen hoặc Performance Max khi dữ liệu và nội dung phù hợp.','Tối đa hóa lượt chuyển đổi hoặc CPA mục tiêu khi chọn đúng chuyển đổi và đo lường đáng tin.','Số lead liên hệ được, đúng nhu cầu và trở thành cơ hội bán hàng.'],sales:['Mua hàng thành công, mã giao dịch và giá trị được đối soát.','Shopping hoặc Performance Max khi có dữ liệu sản phẩm; Search cho nhu cầu cụ thể.','Tối đa hóa giá trị chuyển đổi hoặc ROAS mục tiêu khi giá trị đáng tin; chọn theo thực trạng tài khoản.','Đơn thực, hủy/hoàn, biên lợi nhuận và doanh thu sau đối soát.'],awareness:['Lượt xem, tiếp cận và tần suất phù hợp mục tiêu truyền thông.','Video/YouTube hoặc Display; cân nhắc Demand Gen cho nội dung khám phá.','CPV hoặc CPM theo phân nhóm chiến dịch; không mặc định giá thầu chuyển đổi cho mọi mục tiêu.','Mức xem tiếp, tần suất, độ phù hợp người xem và hành vi sau tiếp cận.'],app:['Cài đặt, đăng ký hoặc mua trong ứng dụng theo mục tiêu.','App với cấu hình cài đặt hoặc tương tác phù hợp.','CPI, CPA hoặc ROAS mục tiêu theo loại chiến dịch và điều kiện dữ liệu.','Người dùng hoạt động, hành động có giá trị và kết quả sau cài.']};document.getElementById('gp-goal').addEventListener('change',e=>{goalPlans[e.target.value].forEach((s,i)=>document.getElementById(['gp-action','gp-campaign','gp-bid','gp-quality'][i]).textContent=s);});
